    internal async Task OrElse_on_value_task_receiver_with_task_delegate_returns_the_receiver_without_running_the_delegate_when_the_receiver_succeeded_when_the_receiver_completes_later()
    {
        var error = Error.Create("Boom.");
        var alternativeCalls = 0;
        var source = new TaskCompletionSource<Result<int>>();
        var receiver = new ValueTask<Result<int>>(source.Task);
        var call = receiver.OrElse(async () => { alternativeCalls++; await Task.Yield(); return Result.Failure<int>(error); });
        Assert.False(call.IsCompleted);
        source.SetResult(Result.Success(2));
        var outcome = await call;

        Assert.Equal(2, outcome.GetValue());
        Assert.Equal(0, alternativeCalls);
    }

